  adapters: JSON.stringify(["0xAdapter1", "0xAdapter2"]),
  blockNumber: "100",
  blockTimestamp: "1700000000",
  ...overrides,
});

describe("envioQueries", () => {
  const sourceChainId = 1514;
  const targetChainId = 42161;
  const yahoAddress = "0xYAHO";
  const fromBlock = 50;

  beforeEach(() => {
    jest.clearAllMocks();
    process.env.RELAYER_ENVIO_YAHO = "http://envio.test/v1/graphql";
  });

  afterAll(() => {
    delete process.env.RELAYER_ENVIO_YAHO;
  });

  describe("toHashiMessageExecutionVars", () => {
    it("should map an Envio row to HashiMessageExecutionVars", () => {
      const mapped = toHashiMessageExecutionVars(makeEnvioRow());
      expect(mapped).toEqual({
        txHash: "0xTxHash",
        timestamp: 1700000000,
        blockNumber: 100,
        messageId: BigInt(12345),
        message: {
          nonce: 3,
          sender: "0xSender",
          targetChainId: 42161,
          receiver: "0xReceiver",
          threshold: 2,
          data: "0xData",
          reporters: ["0xReporter1"],
          adapters: ["0xAdapter1", "0xAdapter2"],
        },
      });
    });
  });

  describe("getDispatchedMessagesFromEnvio", () => {
    it("should throw MissingEnvironmentVariable when RELAYER_ENVIO_YAHO is not set", async () => {
      delete process.env.RELAYER_ENVIO_YAHO;
      await expect(
        getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock)
      ).rejects.toThrow("Missing environment variable: RELAYER_ENVIO_YAHO");
      expect(mockRequest).not.toHaveBeenCalled();
    });

    it("should query the indexer with the source chain, yaho address and fromBlock", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [],
        chain_metadata: [{ latest_processed_block: 200 }],
      });
      await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock);
      expect(mockRequest).toHaveBeenCalledWith("http://envio.test/v1/graphql", expect.any(String), {
        sourceChainId,
        targetChainId,
        chainId: sourceChainId,
        yaho: yahoAddress,
        fromBlock,
        limit: 10,
      });
    });

    it("should checkpoint the indexer head when the batch is not full", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [makeEnvioRow()],
        chain_metadata: [{ latest_processed_block: 200 }],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(1);
      expect(txns[0].message.nonce).toBe(3);
      expect(toBlock).toBe(200);
    });

    it("should checkpoint the last fetched message when the batch is full", async () => {
      const rows = Array.from({ length: 10 }, (_, i) =>
        makeEnvioRow({ id: `row-${i}`, nonce: String(i), blockNumber: String(100 + i) })
      );
      // A full batch now also triggers the drain query for the checkpoint block (109),
      // which holds exactly one row here.
      mockIndexer(rows, 500);
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(10);
      expect(toBlock).toBe(109);
    });

    it("should not move the checkpoint backwards when the indexer head lags fromBlock", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [],
        chain_metadata: [{ latest_processed_block: 40 }],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(0);
      expect(toBlock).toBe(fromBlock);
    });

    it("should checkpoint the last fetched message when chain metadata is missing", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [makeEnvioRow({ blockNumber: "120" })],
        chain_metadata: [],
      });
      const { toBlock } = await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock);
      expect(toBlock).toBe(120);
    });

    it("should keep fromBlock when there are no messages and no chain metadata", async () => {
      mockRequest.mockResolvedValue({
        MessageDispatched: [],
        chain_metadata: [],
      });
      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        fromBlock
      );
      expect(txns).toHaveLength(0);
      expect(toBlock).toBe(fromBlock);
    });

    it("should drain every event of the checkpoint block when a single block overflows the batch", async () => {
      // Block 105 holds 15 matching events but the batch size is 10: the 5 events beyond
      // the batch used to be skipped forever by the `blockNumber > toBlock` cursor.
      const block105 = makeBlockRows(105, 15, 1000);
      mockIndexer(block105, 500);

      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        100,
        10
      );

      const messageIds = txns.map((txn) => txn.messageId.toString());
      expect(messageIds).toHaveLength(15);
      expect(new Set(messageIds).size).toBe(15);
      expect([...messageIds].sort()).toEqual([...block105.map((row) => row.messageId)].sort());
      expect(txns.every((txn) => txn.blockNumber === 105)).toBe(true);
      expect(toBlock).toBe(105);

      // The drain query must target exactly the checkpoint block.
      expect(mockRequest).toHaveBeenCalledWith(
        "http://envio.test/v1/graphql",
        expect.any(String),
        expect.objectContaining({ blockNumber: 105, offset: 0 })
      );
    });

    it("should drain a block whose events exceed the drain page size", async () => {
      const block105 = makeBlockRows(105, 150, 1000);
      mockIndexer(block105, 500);

      const { txns, toBlock } = await getDispatchedMessagesFromEnvio(
        sourceChainId,
        targetChainId,
        yahoAddress,
        100,
        10
      );

      const messageIds = txns.map((txn) => txn.messageId.toString());
      expect(messageIds).toHaveLength(150);
      expect(new Set(messageIds).size).toBe(150);
      expect(toBlock).toBe(105);
      // Page 1 (offset 0) came back full, so a second drain page must have been requested.
      expect(mockRequest).toHaveBeenCalledWith(
        "http://envio.test/v1/graphql",
        expect.any(String),
        expect.objectContaining({ blockNumber: 105, offset: 100 })
      );
    });

    it("should neither re-process nor skip events across consecutive calls", async () => {
      const block105 = makeBlockRows(105, 15, 1000);
      const block106 = makeBlockRows(106, 3, 2000);
      mockIndexer([...block105, ...block106], 500);

      const first = await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, 100, 10);
      expect(first.txns).toHaveLength(15);
      expect(first.toBlock).toBe(105);

      const second = await getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, first.toBlock, 10);
      // Everything after the checkpoint, nothing from block 105 again.
      expect(second.txns.map((txn) => txn.messageId.toString())).toEqual(["2000", "2001", "2002"]);
      expect(second.txns.some((txn) => txn.blockNumber === 105)).toBe(false);
      expect(second.toBlock).toBe(500);

      const allIds = [...first.txns, ...second.txns].map((txn) => txn.messageId.toString());
      expect(new Set(allIds).size).toBe(18);
      expect([...allIds].sort()).toEqual([...block105, ...block106].map((row) => row.messageId).sort());
    });

    it("should wrap indexer failures in DataError", async () => {
      mockRequest.mockRejectedValue(new Error("connection refused"));
      await expect(
        getDispatchedMessagesFromEnvio(sourceChainId, targetChainId, yahoAddress, fromBlock)
      ).rejects.toMatchObject({
        name: "DataError",
        message: "Data error for call: Failed to fetch dispatched messages (envio), Chain ID: 1514, Network: hashi",
      });
    });
  });
});

